300		\begin{enumerate}
301			\item $\mathcal S$ is an SPCC (symmetric, projective, consistent, commuting) strategy of value $1$;
302			\item the state is $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot n} \ot \ket{\mathrm{EPR}_2}$;
303			\item for $b \in \{0,1\}$, $M^{\mathsf{Variable}_1}_b = A_b \ot I$ and $M^{\mathsf{Variable}_5}_b = B_b \ot I$.
304		\end{enumerate}
