665	\subsection{Robust self-testing}\label{subsection:robust-self-testing}
666	
667	Now we prove a robust self-testing theorem for linear constraint system games. First, we specify precisely what we mean by robust self-testing.
668	
669	\begin{definition}[Robust self-testing for LCS games]\label{defn: robust-self-testing}
670		Let $G$ be an LCS game and $\set{\tilde A_e^{(v)}}, \set{\tilde B_e}, \ket\psi$ be a strategy presented via observables. Let $\d:\R \to \R$ be a continuous function with $\d(0) = 0$. We say that $G$ 
671		\emph{self-tests} 
672		the strategy with
673		\emph{perfect completeness}
674		and
675		\emph{$\d$-robustness}
676		if:
677		\begin{itemize}
678			\item The strategy $\set{\tilde A_e^{(v)}}, \set{\tilde B_e}, \ket\psi$ wins the game with probability $1$, and
679			\item for every strategy $\set{A_e^{(v)}}, \set{B_e}, \rho$ which wins with probability at least $1-\e$, there is a local isometry $V = V_A\otimes V_B$ and auxiliary state $\rho_{\text{aux}}$ such that for every $e,v$ with $H(e,v)\neq 0$,
680		\begin{align}
681			\label{eq:robustness-condition-state}
682			\norm{V\rho V^\dagger - \proj \psi\otimes \rho_{\text{aux}}}_1 &\leq \d(\e),\\
683			\drho{V\rho V^\dagger}{V_A A_e^{v}V_A^\dagger\otimes I_A}{(\tilde A_e^{v}\otimes I) \otimes I_B}^2 &\leq \d(\e)\text{, and}\label{eq:robustness-condition-alice}\\
684			\drho{V\rho V^\dagger}{I_A\otimes V_BB_eV_B^\dagger}{I_A\otimes (\tilde B_e\otimes I)}^2 &\leq \d(\e).\label{eq:robustness-condition-bob}
685		\end{align}
686	
687		\end{itemize}
688	\end{definition}
